//! libva bindings generated by `build.rs` (only the calls FFmpeg doesn't wrap), plus helpers.

#![allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code)]

include!(concat!(env!("OUT_DIR"), "/va_bindings.rs"));

use super::{Error, Result};
use std::ffi::CStr;

/// Turns a libva status into an [`Error`] naming the call.
pub(crate) fn check(status: VAStatus, what: &str) -> Result<()> {
    if status == VA_STATUS_SUCCESS as VAStatus {
        return Ok(());
    }
    // SAFETY: vaErrorStr returns a static string for any status.
    let msg = unsafe { CStr::from_ptr(vaErrorStr(status)) }.to_string_lossy();
    Err(Error(format!("{what}: {msg} ({status})")))
}

/// The VA surface behind an `AV_PIX_FMT_VAAPI` frame (FFmpeg stores it in `data[3]`).
///
/// # Safety
/// `frame` must point to a valid VAAPI-format `AVFrame`.
pub(crate) unsafe fn frame_surface(frame: *const ffmpeg_sys_next::AVFrame) -> VASurfaceID {
    (*frame).data[3] as usize as VASurfaceID
}

/// An NV12 image of `width` x `height` (rounded up to even) for sub-rectangle copies.
pub(crate) fn create_nv12_image(display: VADisplay, width: usize, height: usize) -> Result<VAImage> {
    // SAFETY: zeroed POD.
    let mut format: VAImageFormat = unsafe { std::mem::zeroed() };
    format.fourcc = VA_FOURCC_NV12;
    format.byte_order = VA_LSB_FIRST;
    format.bits_per_pixel = 12;
    create_image(display, format, (width + 1) & !1, (height + 1) & !1, "vaCreateImage(NV12)")
}

/// A BGRX (B, G, R, X bytes) image of `width` x `height`.
pub(crate) fn create_bgrx_image(display: VADisplay, width: usize, height: usize) -> Result<VAImage> {
    // SAFETY: zeroed POD.
    let mut format: VAImageFormat = unsafe { std::mem::zeroed() };
    format.fourcc = VA_FOURCC_BGRX;
    format.byte_order = VA_LSB_FIRST;
    format.bits_per_pixel = 32;
    format.depth = 24;
    format.red_mask = 0x00FF_0000;
    format.green_mask = 0x0000_FF00;
    format.blue_mask = 0x0000_00FF;
    create_image(display, format, width, height, "vaCreateImage(BGRX)")
}

fn create_image(display: VADisplay, mut format: VAImageFormat, width: usize, height: usize, what: &str) -> Result<VAImage> {
    // SAFETY: zeroed POD out struct; valid display, format and out pointer.
    let mut image: VAImage = unsafe { std::mem::zeroed() };
    check(unsafe { vaCreateImage(display, &mut format, width as i32, height as i32, &mut image) }, what)?;
    Ok(image)
}
